INSERT INTO stage_comp_seed VALUES
('collaboration', 'Collaboration', 'core', 'Corporate Core', 'Actively works across boundaries, builds inclusive partnerships, shares knowledge, and leverages diverse perspectives to achieve Bunna Bank''s collective goals.', 'Level 1 - Basic for Collaboration', 'Cooperates effectively with immediate team members; shares information openly; listens attentively and respects diverse viewpoints.', 'Level 2 - Intermediate for Collaboration', 'Proactively coordinates across departmental teams; resolves interpersonal friction constructively; offers assistance during peak operational workloads.', 'Level 3 - Advanced for Collaboration', 'Facilitates cross-functional collaboration and joint problem-solving; breaks down organizational silos; establishes collaborative operational routines.', 'Level 4 - Expert for Collaboration', 'Fosters an enterprise-wide culture of partnership and mutual accountability; establishes strategic alliances and collaborative frameworks across all bank directorates.'),
('creativity', 'Creativity', 'core', 'Corporate Core', 'Generates novel, value-adding ideas, embraces innovation, and finds resourceful solutions to enhance banking operations and customer experiences.', 'Level 1 - Basic for Creativity', 'Suggests practical improvements to routine personal tasks; open to adopting new tools and digital processes.', 'Level 2 - Intermediate for Creativity', 'Identifies workflow bottlenecks and proposes innovative, workable solutions; experiments with new ways of delivering customer value.', 'Level 3 - Advanced for Creativity', 'Designs and leads departmental process innovations; applies creative problem-solving to recurring operational hurdles; champions change initiatives.', 'Level 4 - Expert for Creativity', 'Drives bank-wide innovation strategy and digital transformation; cultivates an organizational environment that rewards agile experimentation and creative thinking.'),
('ethical_influence', 'Ethical Influence', 'core', 'Corporate Core', 'Influences others through high ethical integrity, persuasive communication, transparent decision-making, and unwavering adherence to banking compliance.', 'Level 1 - Basic for Ethical Influence', 'Demonstrates personal honesty, transparency, and respect in all daily interactions; adheres strictly to bank code of conduct.', 'Level 2 - Intermediate for Ethical Influence', 'Persuades colleagues and customers using facts and ethical reasoning; addresses and reports compliance concerns constructively; maintains confidential information.', 'Level 3 - Advanced for Ethical Influence', 'Builds widespread consensus for ethical practices; navigates sensitive stakeholder discussions with diplomatic integrity; mentors peers on compliance dilemmas.', 'Level 4 - Expert for Ethical Influence', 'Shapes enterprise-level ethical standards and corporate governance; serves as a trusted advisor to senior executive leadership; champions institutional trust.'),
('execution_mastery', 'Execution Mastery', 'core', 'Corporate Core', 'Consistently delivers outstanding, timely, and error-free operational results through disciplined planning, relentless focus on quality, and accountability.', 'Level 1 - Basic for Execution Mastery', 'Prioritizes daily assignments effectively; meets deadlines reliably; maintains accuracy in routine transaction processing and documentation.', 'Level 2 - Intermediate for Execution Mastery', 'Manages multiple deliverables independently under pressure; anticipates obstacles and takes corrective actions; consistently meets or exceeds performance targets.', 'Level 3 - Advanced for Execution Mastery', 'Drives end-to-end departmental operational excellence; establishes stringent quality benchmarks; ensures flawless execution of complex bank initiatives.', 'Level 4 - Expert for Execution Mastery', 'Establishes bank-wide execution excellence frameworks; ensures organizational agility, accountability, and disciplined delivery of multi-year strategic objectives.'),
('professional_authenticity', 'Professional Authenticity', 'core', 'Corporate Core', 'Exemplifies genuine self-awareness, personal accountability, professionalism, and commitment to continuous growth as a representative of Bunna Bank.', 'Level 1 - Basic for Professional Authenticity', 'Maintains a professional, courteous demeanor; accepts constructive feedback gracefully; takes responsibility for personal actions and mistakes.', 'Level 2 - Intermediate for Professional Authenticity', 'Demonstrates consistent alignment between personal values and bank standards; handles stressful situations calmly and professionally; actively seeks self-development.', 'Level 3 - Advanced for Professional Authenticity', 'Inspires confidence and credibility among internal and external stakeholders; demonstrates high emotional intelligence; coaches others on professional presence.', 'Level 4 - Expert for Professional Authenticity', 'Embodies and personifies Bunna Bank''s brand, culture, and values at an institutional level; commands broad respect across the banking sector.'),
('ambidextrous_leadership', 'Ambidextrous Leadership', 'leadership', 'Bank Leadership', 'Balances operational excellence and daily efficiency with forward-looking exploration, strategic adaptability, and business growth.', 'Level 1 - Basic for Ambidextrous Leadership', 'Executes current operational procedures efficiently while showing openness to organizational change and new operational practices.', 'Level 2 - Intermediate for Ambidextrous Leadership', 'Balances daily service delivery targets with the implementation of departmental improvements and transformation milestones.', 'Level 3 - Advanced for Ambidextrous Leadership', 'Effectively allocates resources between steady-state banking operations and innovation projects; drives operational efficiency while capturing new business opportunities.', 'Level 4 - Expert for Ambidextrous Leadership', 'Leads enterprise-wide strategic agility; successfully steers the bank through digital disruption while maintaining robust operational stability and profitability.'),
('continuous_improvement', 'Continuous Improvement', 'leadership', 'Bank Leadership', 'Relentlessly pursues operational enhancement, cost optimization, service turnaround acceleration, and best-in-class banking practices.', 'Level 1 - Basic for Continuous Improvement', 'Participates actively in team reviews; identifies recurring errors or delays in daily tasks and suggests remedies.', 'Level 2 - Intermediate for Continuous Improvement', 'Analyzes unit performance data to streamline workflows; eliminates non-value-adding steps; implements customer turnaround time reductions.', 'Level 3 - Advanced for Continuous Improvement', 'Champions continuous improvement projects across the division; measures and reports measurable productivity and quality gains.', 'Level 4 - Expert for Continuous Improvement', 'Institutionalizes an enterprise-wide culture of continuous excellence; benchmarks Bunna Bank against global banking standards; drives sustained competitive advantages.'),
('people_leadership', 'People Leadership', 'leadership', 'Bank Leadership', 'Inspires, develops, empowers, and aligns teams to achieve peak performance, fostering inclusion, engagement, and talent retention.', 'Level 1 - Basic for People Leadership', 'Supports team members in onboarding and daily routines; provides clear peer guidance and fosters an inclusive environment.', 'Level 2 - Intermediate for People Leadership', 'Sets clear performance expectations and targets; provides timely, constructive coaching and feedback; recognizes and rewards strong performance.', 'Level 3 - Advanced for People Leadership', 'Builds high-performing teams; identifies and develops future leadership talent; manages employee engagement and resolves complex team dynamics.', 'Level 4 - Expert for People Leadership', 'Shapes enterprise human capital strategy; champions leadership succession pipelines; cultivates an employer-of-choice reputation for Bunna Bank.'),
('prudential_decision_making', 'Prudential Decision Making', 'leadership', 'Bank Leadership', 'Makes sound, timely, and risk-conscious commercial decisions grounded in rigorous data analysis, regulatory compliance, and bank stewardship.', 'Level 1 - Basic for Prudential Decision Making', 'Applies bank guidelines and compliance rules accurately to routine decisions; escalates ambiguous or high-risk situations appropriately.', 'Level 2 - Intermediate for Prudential Decision Making', 'Evaluates risks, costs, and benefits systematically before deciding; exercises sound judgment in standard credit, operational, and customer matters.', 'Level 3 - Advanced for Prudential Decision Making', 'Makes difficult, high-impact operational and risk decisions in complex, uncertain environments; balances risk mitigation with commercial viability.', 'Level 4 - Expert for Prudential Decision Making', 'Makes enterprise-defining strategic decisions affecting bank solvency, asset-liability management, and long-term shareholder value; maintains strong regulatory standing.'),
('self_leadership', 'Self-Leadership', 'leadership', 'Bank Leadership', 'Demonstrates proactive initiative, emotional resilience, personal accountability, and continuous commitment to self-mastery.', 'Level 1 - Basic for Self-Leadership', 'Takes ownership of daily tasks without requiring constant supervision; manages time effectively; demonstrates positive attitude under pressure.', 'Level 2 - Intermediate for Self-Leadership', 'Demonstrates resilience during organizational change; sets personal development goals; takes initiative to acquire new banking competencies.', 'Level 3 - Advanced for Self-Leadership', 'Serves as an exemplar of self-discipline and emotional maturity; effectively manages personal stress in high-stakes situations; pursues continuous executive learning.', 'Level 4 - Expert for Self-Leadership', 'Demonstrates exceptional visionary self-mastery; leads by personal example under intense scrutiny; projects inspiring calm, clarity, and determination.'),
('strategy_management', 'Strategy Management', 'leadership', 'Bank Leadership', 'Formulates, aligns, communicates, and executes strategic roadmaps that drive sustainable market share growth, profitability, and customer value.', 'Level 1 - Basic for Strategy Management', 'Understands the bank''s strategic vision and how daily unit outputs contribute to bank-wide objectives.', 'Level 2 - Intermediate for Strategy Management', 'Translates departmental strategy into actionable quarterly milestones and KPI scorecards; monitors progress and adjusts tactics as needed.', 'Level 3 - Advanced for Strategy Management', 'Conducts environmental scans and competitive analyses; devises robust divisional strategic plans; aligns resources with high-return business opportunities.', 'Level 4 - Expert for Strategy Management', 'Formulates enterprise strategy for Bunna Bank; drives corporate growth, market expansion, and digital ecosystem leadership; creates enduring shareholder value.'),
('agm_and_shareholder_meeting_management', 'AGM & Shareholder Meeting Management', 'technical', 'CEO-COMPANY SECRETARY', 'Demonstrates specialized technical expertise, analytical proficiency, and operational mastery in AGM & Shareholder Meeting Management in CEO-COMPANY SECRETARY to safeguard bank assets and optimize operational outcomes.', 'Level 1 - Basic for AGM & Shareholder Meeting Management', 'Understands fundamental principles, core workflows, and standard operating procedures of AGM & Shareholder Meeting Management; performs foundational tasks under routine supervision.', 'Level 2 - Intermediate for AGM & Shareholder Meeting Management', 'Independently executes key operational tasks, methodologies, and technical tools relating to AGM & Shareholder Meeting Management; resolves routine operational exceptions with accuracy.', 'Level 3 - Advanced for AGM & Shareholder Meeting Management', 'Applies advanced specialized knowledge in AGM & Shareholder Meeting Management to address complex cases; optimizes workflow efficiency, troubleshoots critical incidents, and coaches colleagues.', 'Level 4 - Expert for AGM & Shareholder Meeting Management', 'Serves as institutional authority and subject-matter expert in AGM & Shareholder Meeting Management; establishes departmental governance standards, drives innovation, and ensures strict regulatory compliance.'),
