-- BUNNA BANK S.C. - COMPLETE COMPETENCY & ROLE MAPPING SEED SCRIPT
-- Database: ERP_TEST3
-- Instructions: Open this file in DBeaver and run 'Execute SQL Script' (Alt+X)
-- ============================================================================

BEGIN;

-- STEP 1: Temporary Staging for Competencies
DROP TABLE IF EXISTS stage_comp_seed;
CREATE TEMP TABLE stage_comp_seed (
    code VARCHAR,
    name VARCHAR,
    pillar VARCHAR,
    functional_domain VARCHAR,
    definition TEXT,
    lvl1_def TEXT, lvl1_ind TEXT,
    lvl2_def TEXT, lvl2_ind TEXT,
    lvl3_def TEXT, lvl3_ind TEXT,
    lvl4_def TEXT, lvl4_ind TEXT
);


-- 1.2: Insert new competencies
    name, code, pillar, functional_domain, definition,
    state, status, active, rating_model_id, evaluation_method,
    create_uid, write_uid, create_date, write_date
)
SELECT 
    s.name, s.code, s.pillar, s.functional_domain, s.definition,
    'approved', 'active', true, 1, 'star',
    1, 1, NOW(), NOW()
FROM stage_comp_seed s
WHERE NOT EXISTS (
    SELECT 1 FROM competency_competency c 
    WHERE LOWER(c.code) = LOWER(s.code) OR LOWER(c.name) = LOWER(s.name)
);

-- 1.3: Update existing competencies
UPDATE competency_competency c
SET 
    pillar = s.pillar,
    functional_domain = s.functional_domain,
    definition = s.definition,
    state = 'approved',
    status = 'active',
    active = true,
    write_date = NOW()
FROM stage_comp_seed s
WHERE LOWER(c.code) = LOWER(s.code) OR LOWER(c.name) = LOWER(s.name);

-- 1.4: Proficiency Level 1 (Level 1 - Basic)
    competency_id, level, name, definition, behavioral_indicators,
    create_uid, write_uid, create_date, write_date
)
SELECT 
    c.id, '1', 'Level 1 - Basic', s.lvl1_def, s.lvl1_ind,
    1, 1, NOW(), NOW()
FROM stage_comp_seed s
JOIN competency_competency c ON (LOWER(c.code) = LOWER(s.code) OR LOWER(c.name) = LOWER(s.name))
WHERE NOT EXISTS (
    SELECT 1 FROM competency_proficiency_level l 
    WHERE l.competency_id = c.id AND l.level = '1'
);

UPDATE competency_proficiency_level l
SET 
    name = 'Level 1 - Basic',
    behavioral_indicators = s.lvl1_ind,
    write_date = NOW()
FROM stage_comp_seed s
JOIN competency_competency c ON (LOWER(c.code) = LOWER(s.code) OR LOWER(c.name) = LOWER(s.name))
WHERE l.competency_id = c.id AND l.level = '1';

-- 1.4: Proficiency Level 2 (Level 2 - Intermediate)
    competency_id, level, name, definition, behavioral_indicators,
    create_uid, write_uid, create_date, write_date
)
SELECT 
    c.id, '2', 'Level 2 - Intermediate', s.lvl2_def, s.lvl2_ind,
    1, 1, NOW(), NOW()
FROM stage_comp_seed s
JOIN competency_competency c ON (LOWER(c.code) = LOWER(s.code) OR LOWER(c.name) = LOWER(s.name))
WHERE NOT EXISTS (
    SELECT 1 FROM competency_proficiency_level l 
    WHERE l.competency_id = c.id AND l.level = '2'
);

UPDATE competency_proficiency_level l
SET 
    name = 'Level 2 - Intermediate',
    behavioral_indicators = s.lvl2_ind,
    write_date = NOW()
FROM stage_comp_seed s
JOIN competency_competency c ON (LOWER(c.code) = LOWER(s.code) OR LOWER(c.name) = LOWER(s.name))
WHERE l.competency_id = c.id AND l.level = '2';

-- 1.4: Proficiency Level 3 (Level 3 - Advanced)
    competency_id, level, name, definition, behavioral_indicators,
    create_uid, write_uid, create_date, write_date
)
SELECT 
    c.id, '3', 'Level 3 - Advanced', s.lvl3_def, s.lvl3_ind,
    1, 1, NOW(), NOW()
FROM stage_comp_seed s
JOIN competency_competency c ON (LOWER(c.code) = LOWER(s.code) OR LOWER(c.name) = LOWER(s.name))
WHERE NOT EXISTS (
    SELECT 1 FROM competency_proficiency_level l 
    WHERE l.competency_id = c.id AND l.level = '3'
);

UPDATE competency_proficiency_level l
SET 
    name = 'Level 3 - Advanced',
    behavioral_indicators = s.lvl3_ind,
    write_date = NOW()
FROM stage_comp_seed s
JOIN competency_competency c ON (LOWER(c.code) = LOWER(s.code) OR LOWER(c.name) = LOWER(s.name))
WHERE l.competency_id = c.id AND l.level = '3';

-- 1.4: Proficiency Level 4 (Level 4 - Expert)
    competency_id, level, name, definition, behavioral_indicators,
    create_uid, write_uid, create_date, write_date
)
SELECT 
    c.id, '4', 'Level 4 - Expert', s.lvl4_def, s.lvl4_ind,
    1, 1, NOW(), NOW()
FROM stage_comp_seed s
JOIN competency_competency c ON (LOWER(c.code) = LOWER(s.code) OR LOWER(c.name) = LOWER(s.name))
WHERE NOT EXISTS (
    SELECT 1 FROM competency_proficiency_level l 
    WHERE l.competency_id = c.id AND l.level = '4'
);

UPDATE competency_proficiency_level l
SET 
    name = 'Level 4 - Expert',
    behavioral_indicators = s.lvl4_ind,
    write_date = NOW()
FROM stage_comp_seed s
JOIN competency_competency c ON (LOWER(c.code) = LOWER(s.code) OR LOWER(c.name) = LOWER(s.name))
WHERE l.competency_id = c.id AND l.level = '4';


-- STEP 2: Temporary Staging for Role Requirements
DROP TABLE IF EXISTS stage_req_seed;
CREATE TEMP TABLE stage_req_seed (
    job_name VARCHAR,
    comp_name VARCHAR,
    req_level VARCHAR
);









-- STEP 3: Create Role Mappings and Lines

-- 3.1: Insert Role Mappings for all distinct jobs
    job_position_id, version, state, mapping_name, effective_date,
    is_operating_unit_specific, create_uid, write_uid, create_date, write_date
)
SELECT 
    j.id, 'v1.0', 'approved', j.name->>'en_US', CURRENT_DATE,
    false, 1, 1, NOW(), NOW()
FROM (
    SELECT DISTINCT 
        CASE 
            WHEN sub.job_name = 'Acting/Manager-Work force Planning and Organizational Design Division' 
            THEN 'Manager - Work force Planning and Organizational Design Division'
            WHEN sub.job_name = 'Senior Digital Marketing Officer' 
            THEN 'Digital Marketing Officer'
            ELSE sub.job_name 
        END AS job_name
    FROM stage_req_seed sub
) mapped_jobs
JOIN hr_job j ON LOWER(TRIM(j.name->>'en_US')) = LOWER(TRIM(mapped_jobs.job_name))
WHERE NOT EXISTS (
    SELECT 1 FROM competency_role_mapping m 
    WHERE m.job_position_id = j.id AND m.state IN ('approved', 'under_approval', 'draft')
);

-- 3.2: Insert Competency Role Mapping Lines
    mapping_id, competency_id, pillar, required_proficiency,
    weight, override_default, is_matrix_configured,
    create_uid, write_uid, create_date, write_date
)
SELECT 
    m.id, c.id, c.pillar, r.req_level,
    1.0, true, true,
    1, 1, NOW(), NOW()
FROM (
    -- Deduplicate per job and competency
    SELECT DISTINCT 
        job_name, comp_name, req_level
    FROM stage_req_seed
) r
JOIN hr_job j ON (
    LOWER(TRIM(j.name->>'en_US')) = LOWER(TRIM(r.job_name))
    OR (r.job_name = 'Acting/Manager-Work force Planning and Organizational Design Division' 
        AND j.id = 870)
    OR (r.job_name = 'Senior Digital Marketing Officer' 
        AND LOWER(TRIM(j.name->>'en_US')) = 'digital marketing officer')
)
JOIN competency_role_mapping m ON m.job_position_id = j.id AND m.state IN ('approved', 'under_approval', 'draft')
JOIN competency_competency c ON (LOWER(TRIM(c.name)) = LOWER(TRIM(r.comp_name)) OR LOWER(TRIM(c.code)) = LOWER(TRIM(r.comp_name)))
WHERE NOT EXISTS (
    SELECT 1 FROM competency_role_mapping_line l 
    WHERE l.mapping_id = m.id AND l.competency_id = c.id
);

-- 3.3: Update any existing lines with the new required proficiency
UPDATE competency_role_mapping_line l
SET 
    required_proficiency = r.req_level,
    override_default = true,
    write_date = NOW()
FROM (
    SELECT DISTINCT job_name, comp_name, req_level FROM stage_req_seed
) r
JOIN hr_job j ON (
    LOWER(TRIM(j.name->>'en_US')) = LOWER(TRIM(r.job_name))
    OR (r.job_name = 'Acting/Manager-Work force Planning and Organizational Design Division' AND j.id = 870)
    OR (r.job_name = 'Senior Digital Marketing Officer' AND LOWER(TRIM(j.name->>'en_US')) = 'digital marketing officer')
)
JOIN competency_role_mapping m ON m.job_position_id = j.id AND m.state IN ('approved', 'under_approval', 'draft')
JOIN competency_competency c ON (LOWER(TRIM(c.name)) = LOWER(TRIM(r.comp_name)) OR LOWER(TRIM(c.code)) = LOWER(TRIM(r.comp_name)))
WHERE l.mapping_id = m.id AND l.competency_id = c.id;

-- Cleanup temporary tables
DROP TABLE IF EXISTS stage_comp_seed;
DROP TABLE IF EXISTS stage_req_seed;

COMMIT;

-- Verification query
SELECT 
    (SELECT count(*) FROM competency_competency) AS total_competencies,
    (SELECT count(*) FROM competency_proficiency_level) AS total_proficiency_levels,
    (SELECT count(*) FROM competency_role_mapping) AS total_role_mappings,
    (SELECT count(*) FROM competency_role_mapping_line) AS total_mapped_lines;
